use akar_components::{
    akar_badge, akar_badge_styled, akar_button, akar_card, akar_container, akar_heading,
    akar_label, akar_link, akar_navbar, akar_paragraph, akar_separator, akar_stat, akar_tab_bar,
    scroll_area_begin, scroll_area_end, AKAR_THEME_LIGHT, BadgeStyle, BadgeVariant, BoxStyle,
    ButtonVariant, CardSlots, CardStyle, FontFamily, HeadingLevel, NavbarStyle, TextStyle,
    TabVariant,
};
use akar_core::AkarCore;
use akar_layout::{
    length, AlignItems, Dimension, Display, FlexDirection, JustifyContent, Layout, NodeId, Size,
    Style,
};

use crate::site::Site;

const THEME: akar_components::AkarTheme = AKAR_THEME_LIGHT;

fn leaf(style: Style) -> Style {
    style
}

pub struct AkarSite {
    root: NodeId,
    navbar_root: NodeId,
    logo_node: NodeId,
    feat_link: NodeId,
    comp_link: NodeId,
    github_link: NodeId,
    scroll_container: NodeId,
    scroll_y: f32,
    hero_root: NodeId,
    h1_node: NodeId,
    subtitle_node: NodeId,
    cta_solid: NodeId,
    cta_outline: NodeId,
    stats_root: NodeId,
    stat_nodes: [NodeId; 3],
    cards_root: NodeId,
    card_roots: [NodeId; 3],
    card_headings: [NodeId; 3],
    card_paras: [NodeId; 3],
    why_root: NodeId,
    why_h2: NodeId,
    why_body_para: NodeId,
    why_h4s: [NodeId; 4],
    why_paras: [NodeId; 4],
    showcase_root: NodeId,
    showcase_badges_h3: NodeId,
    badge_nodes: [NodeId; 7],
    showcase_buttons_h3: NodeId,
    btn_solid: NodeId,
    btn_outline: NodeId,
    btn_ghost: NodeId,
    showcase_tabs_h3: NodeId,
    tab_bar_node: NodeId,
    active_tab: usize,
    footer_root: NodeId,
    separator_node: NodeId,
    footer_col_headings: [NodeId; 3],
    footer_link_nodes: [NodeId; 6],
    copyright_label: NodeId,
}

impl AkarSite {
    pub fn new() -> Self {
        let n = || NodeId::new(0);
        Self {
            root: n(),
            navbar_root: n(),
            logo_node: n(),
            feat_link: n(),
            comp_link: n(),
            github_link: n(),
            scroll_container: n(),
            scroll_y: 0.0,
            hero_root: n(),
            h1_node: n(),
            subtitle_node: n(),
            cta_solid: n(),
            cta_outline: n(),
            stats_root: n(),
            stat_nodes: [n(); 3],
            cards_root: n(),
            card_roots: [n(); 3],
            card_headings: [n(); 3],
            card_paras: [n(); 3],
            why_root: n(),
            why_h2: n(),
            why_body_para: n(),
            why_h4s: [n(); 4],
            why_paras: [n(); 4],
            showcase_root: n(),
            showcase_badges_h3: n(),
            badge_nodes: [n(); 7],
            showcase_buttons_h3: n(),
            btn_solid: n(),
            btn_outline: n(),
            btn_ghost: n(),
            showcase_tabs_h3: n(),
            tab_bar_node: n(),
            active_tab: 0,
            footer_root: n(),
            separator_node: n(),
            footer_col_headings: [n(); 3],
            footer_link_nodes: [n(); 6],
            copyright_label: n(),
        }
    }
}

impl Site for AkarSite {
    fn name(&self) -> &str {
        "akar"
    }

    fn root(&self) -> NodeId {
        self.root
    }

    fn build_layout(&mut self, layout: &mut Layout) {
        let zero_gap = taffy::geometry::Size {
            width: length(0.0f32),
            height: length(0.0f32),
        };

        let root = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Column,
            size: Size {
                width: Dimension::percent(1.0),
                height: Dimension::percent(1.0),
            },
            ..Default::default()
        });

        let navbar_root = layout.new_leaf(Style::default());
        let logo_node = layout.new_leaf(Style {
            size: Size {
                width: length(120.0f32),
                height: length(40.0f32),
            },
            ..Default::default()
        });
        let feat_link = layout.new_leaf(Style {
            size: Size {
                width: length(100.0f32),
                height: length(24.0f32),
            },
            ..Default::default()
        });
        let comp_link = layout.new_leaf(Style {
            size: Size {
                width: length(120.0f32),
                height: length(24.0f32),
            },
            ..Default::default()
        });
        let github_link = layout.new_leaf(Style {
            size: Size {
                width: length(80.0f32),
                height: length(24.0f32),
            },
            ..Default::default()
        });

        layout.set_children(navbar_root, &[logo_node, feat_link, comp_link, github_link]);
        layout.set_style(
            navbar_root,
            Style {
                display: Display::Flex,
                flex_direction: FlexDirection::Row,
                align_items: Some(AlignItems::CENTER),
                justify_content: Some(JustifyContent::SPACE_BETWEEN),
                flex_shrink: 0.0,
                size: Size {
                    width: Dimension::percent(1.0),
                    height: length(64.0f32),
                },
                padding: taffy::geometry::Rect {
                    left: length(48.0f32),
                    right: length(48.0f32),
                    top: length(0.0f32),
                    bottom: length(0.0f32),
                },
                ..Default::default()
            },
        );

        let scroll_container = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Column,
            flex_grow: 1.0,
            ..Default::default()
        });

        let hero_root = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Column,
            align_items: Some(AlignItems::CENTER),
            justify_content: Some(JustifyContent::CENTER),
            flex_shrink: 0.0,
            size: Size {
                width: Dimension::percent(1.0),
                height: length(480.0f32),
            },
            gap: taffy::geometry::Size {
                width: length(0.0f32),
                height: length(16.0f32),
            },
            ..Default::default()
        });
        let h1_node = layout.new_leaf(Style {
            size: Size {
                width: Dimension::percent(1.0),
                height: length(60.0f32),
            },
            ..Default::default()
        });
        let subtitle_node = layout.new_leaf(Style {
            size: Size {
                width: length(600.0f32),
                height: length(48.0f32),
            },
            ..Default::default()
        });
        let cta_solid = layout.new_leaf(Style {
            size: Size {
                width: length(160.0f32),
                height: length(44.0f32),
            },
            ..Default::default()
        });
        let cta_outline = layout.new_leaf(Style {
            size: Size {
                width: length(160.0f32),
                height: length(44.0f32),
            },
            ..Default::default()
        });
        layout.set_children(hero_root, &[h1_node, subtitle_node, cta_solid, cta_outline]);

        let stats_root = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Row,
            flex_shrink: 0.0,
            size: Size {
                width: Dimension::percent(1.0),
                height: length(160.0f32),
            },
            gap: taffy::geometry::Size {
                width: length(24.0f32),
                height: length(0.0f32),
            },
            padding: taffy::geometry::Rect {
                left: length(48.0f32),
                right: length(48.0f32),
                top: length(0.0f32),
                bottom: length(0.0f32),
            },
            ..Default::default()
        });
        let stat_nodes: [NodeId; 3] = std::array::from_fn(|_| {
            layout.new_leaf(Style {
                flex_grow: 1.0,
                size: Size {
                    width: Dimension::auto(),
                    height: length(140.0f32),
                },
                ..Default::default()
            })
        });
        layout.set_children(stats_root, &stat_nodes);

        let cards_root = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Row,
            flex_shrink: 0.0,
            size: Size {
                width: Dimension::percent(1.0),
                height: length(280.0f32),
            },
            gap: taffy::geometry::Size {
                width: length(24.0f32),
                height: length(0.0f32),
            },
            padding: taffy::geometry::Rect {
                left: length(48.0f32),
                right: length(48.0f32),
                top: length(0.0f32),
                bottom: length(0.0f32),
            },
            ..Default::default()
        });
        let mut card_roots = [NodeId::new(0); 3];
        let mut card_headings = [NodeId::new(0); 3];
        let mut card_paras = [NodeId::new(0); 3];
        for i in 0..3 {
            let card_root = layout.new_leaf(Style {
                display: Display::Flex,
                flex_direction: FlexDirection::Column,
                flex_grow: 1.0,
                size: Size {
                    width: Dimension::auto(),
                    height: length(260.0f32),
                },
                padding: taffy::geometry::Rect {
                    left: length(24.0f32),
                    right: length(24.0f32),
                    top: length(28.0f32),
                    bottom: length(24.0f32),
                },
                gap: taffy::geometry::Size {
                    width: length(0.0f32),
                    height: length(8.0f32),
                },
                ..Default::default()
            });
            let heading = layout.new_leaf(Style::default());
            let para = layout.new_leaf(Style {
                size: Size {
                    width: Dimension::percent(1.0),
                    height: length(120.0f32),
