        let col_product = layout.new_leaf(Style {
            display: Display::Flex,
            flex_direction: FlexDirection::Column,
            flex_grow: 1.0,
            gap: col_gap,
            ..Default::default()
        });
        let col_resources = layout.new_leaf(Style {
